import { formatDate } from '@angular/common';
import { computed, inject, Injectable, resource, signal } from '@angular/core';
import {
    Booking,
    downloadFile,
    jsonToCsv,
    OrganisationService,
    SettingsService,
} from '@placeos/common';
import { format, isSameDay } from 'date-fns';
import { REMOVE_KEYS, ReportsStateService } from '../reports-state.service';

export interface ReportOptions {
    /** Zones to check available space for */
    zones?: string[];
    /** Start time of the report in ms */
    start?: number;
    /** End time of the report in ms */
    end?: number;
}

@Injectable({
    providedIn: 'root',
})
export class LockersReportService {
    private _settings = inject(SettingsService);
    private _org = inject(OrganisationService);
    private _report = inject(ReportsStateService);

    private _options = signal<ReportOptions>({});

    public readonly loading = this._report.loading;
    public readonly options = this._options.asReadonly();

    public readonly bookings = computed(
        () => this._report.bookings() as Booking[],
    );

    public readonly daily_stats = computed(() => {
        const bookings = this.bookings();
        const days = {};
        for (const booking of bookings) {
            const date = format(booking.date, 'yyyy-MM-dd');
            if (!days[date]) {
                days[date] = {
                    date: booking.date,
                    bookings: [],
                };
            }
            days[date].bookings.push(booking);
        }
        return days;
    });

    /**
     * Values that select the locker counts. Equal values keep the same
     * object, so date changes do not load the lockers again. Building,
     * region, level and Generate Report changes do.
     */
    private readonly _params = computed(
        () => {
            const use_region = !!this._settings.get('app.use_region');
            const building = this._org.active_building();
            const region = this._org.active_region();
            let zones = (this._options().zones || []).filter(
                (z: unknown) => z !== -1 && z !== 'All',
            );
            if (!zones.length) {
                zones = (
                    use_region
                        ? this._org.levelsForRegion(region)
                        : this._org.levelsForBuilding(building)
                )
                    .filter((_) => _.tags.includes('lockers'))
                    .map((_) => _.id);
            }
            return {
                zones,
                scope_id: use_region ? region?.id : building?.id,
                version: this._report.inventory_version(),
            };
        },
        { equal: (a, b) => JSON.stringify(a) === JSON.stringify(b) },
    );

    private readonly _counts = resource({
        params: () => this._params(),
        defaultValue: {} as Record<string, number>,
        loader: async ({ params: { zones, scope_id } }) => {
            if (!zones.length || !scope_id) return {};
            // Shares the request that the report counts make at the same time
            const lockers = await this._report
                .queryLockers(scope_id)
                .catch(() => []);
            const list = zones.map(
                (z) =>
                    [
                        z,
                        lockers.filter((locker) => locker.zones?.includes(z))
                            .length,
                    ] as [string, number],
            );
            const mapping: Record<string, number> = {};
            list.forEach(
                ([id, count]) => (mapping[id] = Math.max(count || 0, 1)),
            );
            return mapping;
        },
    });
    public readonly counts = this._counts.value;

    public setOptions(options: Partial<ReportOptions>) {
        this._options.set({ ...this._options(), ...options });
        this._report.setOptions(options);
    }

    public generateReport() {
        this._report.setOptions({ type: 'lockers' });
        this._report.generateReport();
    }

    public async downloadReport() {
        const options = this._options();
        const bookings = this.bookings();
        if (!bookings?.length) return;
        const is_same = isSameDay(options.start, options.end);
        const date = is_same
            ? format(options.start, 'yyyy-MM-dd')
            : `${format(options.start, 'yyyy-MM-dd')}-${format(
                  options.end,
                  'yyyy-MM-dd',
              )}`;
        downloadFile(
            `report+assets+${date}.tsv`,
            jsonToCsv(
                bookings.map((booking) => {
                    const b: any = booking.toJSON();
                    const fmt_str = 'MMM d, y, h:mm a';
                    b.start = formatDate(b.booking_start * 1000, fmt_str, 'en');
                    b.end = formatDate(b.booking_end * 1000, fmt_str, 'en');
                    for (const key of REMOVE_KEYS) delete b[key];
                    return b;
                }),
                '\t',
            ),
        );
    }
}
